@section('content')<div x-data="mediaLibrary"><div class="admin-page-heading"><h1>کتابخانه رسانه</h1><span x-text="pagination.total+' فایل'"></span></div><form class="admin-panel media-upload-form" @submit.prevent="upload($event)"><label>فایل<input type="file" name="file" required accept="image/jpeg,image/png,image/webp,application/pdf"></label><label>توضیح جایگزین<input name="alt" maxlength="250"></label><button class="primary-button" :disabled="busy">بارگذاری</button></form><p class="form-error" x-text="error" role="alert"></p><div class="media-grid"><template x-for="item in items" :key="item.id"><article class="media-card"><div class="media-preview"><template x-if="item.mime_type.startsWith('image/')"><img :src="mediaUrl(item)" :alt="item.alt||''" loading="lazy"></template><span x-show="!item.mime_type.startsWith('image/')" x-text="item.mime_type==='application/pdf'?'PDF':'فایل'"></span></div><strong x-text="item.alt||item.original_name"></strong><small x-text="item.mime_type+' · '+Math.round(item.size/1024)+' KB'"></small><div><a :href="mediaUrl(item)" target="_blank" rel="noopener noreferrer">مشاهده</a><button type="button" class="danger-link" @click="remove(item)">حذف</button></div></article></template></div><nav class="pagination"><button type="button" :disabled="page<=1" @click="page--;load()">قبلی</button><span x-text="page"></span><button type="button" :disabled="page>=pagination.last_page" @click="page++;load()">بعدی</button></nav></div>@endsection